																if (item.channelId !== notification.id) {
																	return item;
																}

																if (!item.escalation) {
																	return item;
																}

																return {
																	channelId: item.channelId,
																	escalation: {
																		...item.escalation,
																		delayMinutes,
																	},
																};
															})
