													)}
												</MenuItem>
												<MenuItem value={900000}>
													{t(
														"pages.createMonitor.form.geoChecks.option.interval.value.fifteenMinutes"
													)}
												</MenuItem>
												<MenuItem value={1800000}>
													{t(
														"pages.createMonitor.form.geoChecks.option.interval.value.thirtyMinutes"
													)}
												</MenuItem>
											</Select>
										)}
									/>
								</Stack>
							)}
						</Stack>
					}
