import { useMemo, useState } from "react";
import { useEffect } from "react";
import { logger } from "@/Utils/logger";
import { useParams, useLocation, useNavigate } from "react-router";
import { useForm, Controller } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useTheme } from "@mui/material";
import Stack from "@mui/material/Stack";
import RadioGroup from "@mui/material/RadioGroup";
import FormControl from "@mui/material/FormControl";
import { Trans, useTranslation } from "react-i18next";
import MenuItem from "@mui/material/MenuItem";
import Typography from "@mui/material/Typography";
import Link from "@mui/material/Link";
import Divider from "@mui/material/Divider";
import IconButton from "@mui/material/IconButton";
import { Trash2 } from "lucide-react";
import { HeaderDeleteControls } from "@/Components/monitors";
import { GeoContinents } from "@/Types/GeoCheck";

import { BasePage, ConfigBox } from "@/Components/design-elements";
import {
	RadioWithDescription,
	Button,
	TextField,
	Select,
	Autocomplete,
	SwitchComponent as Switch,
	SliderWithLabel,
	Dialog,
} from "@/Components/inputs";
import { SPACING, LAYOUT } from "@/Utils/Theme/constants";
import { useGet, usePost, usePatch, useDelete } from "@/Hooks/UseApi";
import { useMonitorForm } from "@/Hooks/useMonitorForm";
import {
	type Monitor,
	type MonitorType,
	type GamesMap,
	supportsGeoCheck,
} from "@/Types/Monitor";
import type { Notification } from "@/Types/Notification";
import type { MonitorFormData } from "@/Validation/monitor";

interface GeneralSettingsConfig {
	urlLabel: string;
	urlPlaceholder: string;
	namePlaceholder: string;
	showUrl: boolean;
	showPort: boolean;
	showGameSelect: boolean;
	showSecret: boolean;
	showGrpcServiceName: boolean;
	showIgnoreTls: boolean;
}

const getGeneralSettingsConfig = (
	type: MonitorType,
	t: (key: string) => string
): GeneralSettingsConfig => {
	const configs: Record<string, GeneralSettingsConfig> = {
		http: {
			urlLabel: t("pages.createMonitor.form.general.option.url.label"),
			urlPlaceholder: t("pages.createMonitor.form.general.option.url.placeholder"),
			namePlaceholder: t("pages.createMonitor.form.general.option.name.placeholder"),
			showUrl: true,
			showPort: false,
			showGameSelect: false,
			showSecret: false,
			showGrpcServiceName: false,
			showIgnoreTls: false,
		},
		ping: {
			urlLabel: t("pages.createMonitor.form.general.option.host.label"),
			urlPlaceholder: t("pages.createMonitor.form.general.option.host.placeholder"),
			namePlaceholder: t("pages.createMonitor.form.general.option.name.placeholder"),
			showUrl: true,
			showPort: false,
			showGameSelect: false,
			showSecret: false,
			showGrpcServiceName: false,
			showIgnoreTls: false,
		},
		docker: {
			urlLabel: t("pages.createMonitor.form.general.option.container.label"),
			urlPlaceholder: t("pages.createMonitor.form.general.option.container.placeholder"),
			namePlaceholder: t("pages.createMonitor.form.general.option.name.placeholder"),
			showUrl: true,
			showPort: false,
			showGameSelect: false,
			showSecret: false,
			showGrpcServiceName: false,
			showIgnoreTls: false,
		},
		port: {
			urlLabel: t("pages.createMonitor.form.general.option.url.label"),
			urlPlaceholder: t("pages.createMonitor.form.general.option.url.placeholder"),
			namePlaceholder: t("pages.createMonitor.form.general.option.name.placeholder"),
			showUrl: true,
			showPort: true,
			showGameSelect: false,
			showSecret: false,
			showGrpcServiceName: false,
			showIgnoreTls: false,
		},
		game: {
			urlLabel: t("pages.createMonitor.form.general.option.url.label"),
			urlPlaceholder: t("pages.createMonitor.form.general.option.url.placeholder"),
			namePlaceholder: t("pages.createMonitor.form.general.option.name.placeholder"),
			showUrl: true,
			showPort: true,
			showGameSelect: true,
			showSecret: false,
			showGrpcServiceName: false,
			showIgnoreTls: false,
		},
		grpc: {
			urlLabel: t("pages.createMonitor.form.general.option.host.label"),
			urlPlaceholder: t("pages.createMonitor.form.general.option.host.placeholder"),
			namePlaceholder: t("pages.createMonitor.form.general.option.name.placeholder"),
			showUrl: true,
			showPort: true,
			showGameSelect: false,
			showSecret: false,
			showGrpcServiceName: true,
			showIgnoreTls: true,
		},
		pagespeed: {
			urlLabel: t("pages.createMonitor.form.general.option.url.label"),
			urlPlaceholder: t("pages.createMonitor.form.general.option.url.placeholder"),
			namePlaceholder: t("pages.createMonitor.form.general.option.name.placeholder"),
			showUrl: true,
			showPort: false,
			showGameSelect: false,
			showSecret: false,
			showGrpcServiceName: false,
			showIgnoreTls: false,
		},
		hardware: {
			urlLabel: t("pages.createMonitor.form.general.option.url.label"),
			urlPlaceholder: t("pages.createMonitor.form.general.option.url.placeholder"),
			namePlaceholder: t("pages.createMonitor.form.general.option.name.placeholder"),
			showUrl: true,
			showPort: false,
			showGameSelect: false,
			showSecret: true,
			showGrpcServiceName: false,
			showIgnoreTls: false,
		},
		websocket: {
			urlLabel: t("pages.createMonitor.form.general.option.wsUrl.label"),
			urlPlaceholder: t("pages.createMonitor.form.general.option.wsUrl.placeholder"),
			namePlaceholder: t("pages.createMonitor.form.general.option.name.placeholder"),
			showUrl: true,
			showPort: false,
			showGameSelect: false,
			showSecret: false,
			showGrpcServiceName: false,
			showIgnoreTls: true,
		},
	};
	return configs[type] || configs.http;
};

const CreateMonitorPage = () => {
	const theme = useTheme();
	const { t } = useTranslation();
	const { monitorId } = useParams();
	const location = useLocation();
	const navigate = useNavigate();
	const isEditMode = Boolean(monitorId);

	// Extract page type from URL path (e.g., /pagespeed/create -> pagespeed)
	const pageType = useMemo(() => {
		const pathSegments = location.pathname.split("/").filter(Boolean);
		const firstSegment = pathSegments[0];
		if (firstSegment === "pagespeed") return "pagespeed";
		if (firstSegment === "infrastructure") return "hardware";
		return "uptime";
	}, [location.pathname]);

	const showTypeSelector = pageType === "uptime" && !isEditMode;
	const defaultType: MonitorType =
		pageType === "pagespeed"
			? "pagespeed"
			: pageType === "hardware"
				? "hardware"
				: "http";

	const { data: existingMonitor, refetch: refetchMonitor } = useGet<Monitor>(
		isEditMode ? `/monitors/${monitorId}` : null
	);

	const { data: notifications } = useGet<Notification[]>("/notifications/team");
	const { data: games } = useGet<GamesMap>("/monitors/games");

	const { schema, defaults } = useMonitorForm({
		data: existingMonitor ?? null,
		defaultType,
	});

	const form = useForm<MonitorFormData>({
		resolver: zodResolver(schema),
		defaultValues: defaults,
	});
	const { control, watch, handleSubmit, clearErrors } = form;

	useEffect(() => {
		form.reset(defaults);
	}, [defaults, form]);

	const watchedType = watch("type") as MonitorType;

	const watchedUseAdvancedMatching = watch("useAdvancedMatching") as boolean;
	const watchGeoCheckEnabled = watch("geoCheckEnabled") as boolean;

	useEffect(() => {
		clearErrors();
	}, [watchedType, clearErrors]);

	const generalSettingsConfig = useMemo(
		() => getGeneralSettingsConfig(watchedType, t),
		[watchedType, t]
	);

	const { post, loading: isCreating } = usePost<MonitorFormData, Monitor>();
	const { patch, loading: isUpdating } = usePatch<MonitorFormData, Monitor>();
	const isSubmitting = isCreating || isUpdating;
	// Delete functionality
	const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
	const { deleteFn, loading: isDeleting } = useDelete();

	const handleDeleteClick = () => {
		setIsDeleteDialogOpen(true);
	};

	const handleDeleteConfirm = async () => {
		if (!monitorId) return;
		await deleteFn(`/monitors/${monitorId}`);
		setIsDeleteDialogOpen(false);
		// Navigate based on page type
		if (pageType === "pagespeed") {
			navigate("/pagespeed");
		} else if (pageType === "hardware") {
			navigate("/infrastructure");
		} else {
			navigate("/uptime");
		}
	};

	const handleDeleteCancel = () => {
		setIsDeleteDialogOpen(false);
	};

	const onSubmit = async (data: MonitorFormData) => {
		let result;
		if (isEditMode && monitorId) {
			result = await patch(`/monitors/${monitorId}`, data);
		} else {
			result = await post("/monitors", data);
		}

		if (result?.success) {
			if (pageType === "pagespeed") {
				navigate("/pagespeed");
			} else if (pageType === "hardware") {
				navigate("/infrastructure");
			} else {
				navigate("/uptime");
			}
		}
	};

	const onError = (errors: unknown) => {
		logger.debug("Monitor creation validation errors", errors);
	};

	return (
		<BasePage
			component="form"
			onSubmit={handleSubmit(onSubmit, onError)}
		>
			<HeaderDeleteControls
				monitor={existingMonitor}
				isAdmin={true}
				refetch={refetchMonitor}
				onDelete={handleDeleteClick}
			/>
			{/* Monitor Type Selection - only shown for uptime monitors */}
			{showTypeSelector && (
				<ConfigBox
					title={t("pages.createMonitor.form.type.title")}
					subtitle={t("pages.createMonitor.form.type.description")}
					rightContent={
						<Controller
							name="type"
							control={control}
							render={({ field, fieldState }) => (
								<FormControl error={!!fieldState.error}>
									<RadioGroup
										{...field}
										sx={{ gap: theme.spacing(LAYOUT.MD) }}
									>
										<RadioWithDescription
											value="http"
											label={t("pages.common.monitors.monitorTypes.optionHttp")}
											description={t(
												"pages.createMonitor.form.type.optionHttpDescription"
											)}
										/>
										<RadioWithDescription
											value="ping"
											label={t("pages.common.monitors.monitorTypes.optionPing")}
											description={t(
												"pages.createMonitor.form.type.optionPingDescription"
											)}
										/>
										<RadioWithDescription
											value="docker"
											label={t("pages.common.monitors.monitorTypes.optionDocker")}
											description={t(
												"pages.createMonitor.form.type.optionDockerDescription"
											)}
										/>
										<RadioWithDescription
											value="port"
											label={t("pages.common.monitors.monitorTypes.optionPort")}
											description={t(
												"pages.createMonitor.form.type.optionPortDescription"
											)}
										/>
										<RadioWithDescription
											value="game"
											label={t("pages.common.monitors.monitorTypes.optionGame")}
											description={t(
												"pages.createMonitor.form.type.optionGameDescription"
											)}
										/>
										<RadioWithDescription
											value="grpc"
											label={t("pages.common.monitors.monitorTypes.optionGrpc")}
											description={t(
												"pages.createMonitor.form.type.optionGrpcDescription"
											)}
										/>
										<RadioWithDescription
											value="websocket"
											label={t("pages.common.monitors.monitorTypes.optionWebSocket")}
											description={t(
												"pages.createMonitor.form.type.optionWebSocketDescription"
											)}
										/>
									</RadioGroup>
								</FormControl>
							)}
						/>
					}
				/>
			)}

			<ConfigBox
				title={t("pages.createMonitor.form.general.title")}
				subtitle={t(`pages.createMonitor.form.general.description.${watchedType}`)}
				rightContent={
					<Stack spacing={theme.spacing(LAYOUT.MD)}>
						{/* URL/Host/Container field - not shown for hardware */}
						{generalSettingsConfig.showUrl && (
							<Controller
								name="url"
								control={control}
								render={({ field, fieldState }) => (
									<TextField
										{...field}
										type="text"
										fieldLabel={generalSettingsConfig.urlLabel}
										placeholder={generalSettingsConfig.urlPlaceholder}
										fullWidth
										disabled={isEditMode}
										error={!!fieldState.error}
										helperText={fieldState.error?.message ?? ""}
									/>
								)}
							/>
						)}

						{/* Port field - only for port and game types */}
						{generalSettingsConfig.showPort && (
							<Controller
								name="port"
								control={control}
								render={({ field, fieldState }) => (
									<TextField
										{...field}
										value={field.value === 0 ? "" : field.value}
										onChange={(e) => {
											const val = e.target.value;
											field.onChange(val === "" ? 0 : Number(val));
										}}
										type="number"
										fieldLabel={t("pages.createMonitor.form.general.option.port.label")}
										placeholder={t(
											"pages.createMonitor.form.general.option.port.placeholder"
										)}
										fullWidth
										error={!!fieldState.error}
										helperText={fieldState.error?.message ?? ""}
									/>
								)}
							/>
						)}

						{/* Game select - only for game type */}
						{generalSettingsConfig.showGameSelect && (
							<Controller
								name="gameId"
								control={control}
								render={({ field, fieldState }) => (
									<Select
										{...field}
										value={field.value ?? ""}
										fieldLabel={t("pages.createMonitor.form.general.option.game.label")}
										error={!!fieldState.error}
									>
										<MenuItem value="">
											{t("pages.createMonitor.form.general.option.game.placeholder")}{" "}
										</MenuItem>
										{games &&
											Object.entries(games).map(([key, game]) => (
												<MenuItem
													key={key}
													value={key}
												>
													{game.name}
												</MenuItem>
											))}
									</Select>
								)}
							/>
						)}

						{/* gRPC Service Name field - only for grpc type */}
						{generalSettingsConfig.showGrpcServiceName && (
							<Controller
								name="grpcServiceName"
								control={control}
								render={({ field, fieldState }) => (
									<TextField
										{...field}
										value={field.value ?? ""}
										type="text"
										fieldLabel={t(
											"pages.createMonitor.form.general.option.grpcServiceName.label"
										)}
										placeholder={t(
											"pages.createMonitor.form.general.option.grpcServiceName.placeholder"
										)}
										fullWidth
										error={!!fieldState.error}
										helperText={fieldState.error?.message ?? ""}
									/>
								)}
							/>
						)}

						{/* Secret field - only for hardware type */}
						{generalSettingsConfig.showSecret && (
							<Controller
								name="secret"
								control={control}
								render={({ field, fieldState }) => (
									<TextField
										{...field}
										value={field.value ?? ""}
										type="text"
										fieldLabel={t("pages.createMonitor.form.general.option.secret.label")}
										placeholder={t(
											"pages.createMonitor.form.general.option.secret.placeholder"
										)}
										fullWidth
										error={!!fieldState.error}
										helperText={fieldState.error?.message ?? ""}
									/>
								)}
							/>
						)}

						<Controller
							name="name"
							control={control}
							render={({ field, fieldState }) => (
								<TextField
									{...field}
									type="text"
									fieldLabel={t("pages.createMonitor.form.general.option.name.label")}
									placeholder={generalSettingsConfig.namePlaceholder}
									fullWidth
									error={!!fieldState.error}
									helperText={fieldState.error?.message ?? ""}
								/>
							)}
						/>
					</Stack>
				}
			/>

			<ConfigBox
				title={t("pages.createMonitor.form.frequency.title")}
				subtitle={t("pages.createMonitor.form.frequency.description")}
				rightContent={
					<Controller
						name="interval"
						control={control}
						render={({ field, fieldState }) => (
							<Select
								{...field}
								value={field.value ?? 60000}
								fieldLabel={t(
									"pages.createMonitor.form.frequency.option.frequency.label"
								)}
								error={!!fieldState.error}
							>
								<MenuItem value={15000}>
									{t(
										"pages.createMonitor.form.frequency.option.frequency.value.fifteenSeconds"
									)}
								</MenuItem>
								<MenuItem value={30000}>
									{t(
										"pages.createMonitor.form.frequency.option.frequency.value.thirtySeconds"
									)}
								</MenuItem>
								<MenuItem value={60000}>
									{t(
										"pages.createMonitor.form.frequency.option.frequency.value.oneMinute"
									)}
								</MenuItem>
								<MenuItem value={120000}>
									{t(
										"pages.createMonitor.form.frequency.option.frequency.value.twoMinutes"
									)}
								</MenuItem>
								<MenuItem value={180000}>
									{t(
										"pages.createMonitor.form.frequency.option.frequency.value.threeMinutes"
									)}
								</MenuItem>
								<MenuItem value={240000}>
									{t(
										"pages.createMonitor.form.frequency.option.frequency.value.fourMinutes"
									)}
								</MenuItem>
								<MenuItem value={300000}>
									{t(
										"pages.createMonitor.form.frequency.option.frequency.value.fiveMinutes"
									)}
								</MenuItem>
								<MenuItem value={600000}>
									{t(
										"pages.createMonitor.form.frequency.option.frequency.value.tenMinutes"
									)}
								</MenuItem>
								<MenuItem value={900000}>
									{t(
										"pages.createMonitor.form.frequency.option.frequency.value.fifteenMinutes"
									)}
								</MenuItem>
								<MenuItem value={1800000}>
									{t(
										"pages.createMonitor.form.frequency.option.frequency.value.thirtyMinutes"
									)}
								</MenuItem>
							</Select>
						)}
					/>
				}
			/>

			{/* Alert Thresholds - only for hardware type */}
			{generalSettingsConfig.showSecret && (
				<ConfigBox
					title={t("pages.createMonitor.form.thresholds.title")}
					subtitle={t("pages.createMonitor.form.thresholds.description")}
					rightContent={
						<Stack spacing={theme.spacing(LAYOUT.MD)}>
							<Controller
								name="cpuAlertThreshold"
								control={control}
								render={({ field }) => (
									<SliderWithLabel
										{...field}
										sliderMaxWidth={{ xs: "100%", md: "50%" }}
										fieldLabel={t(
											"pages.createMonitor.form.thresholds.option.cpuThreshold.label"
										)}
										min={0}
										max={100}
										step={1}
										valueLabelDisplay="auto"
										valueLabelFormat={(value) => `${value}%`}
									/>
								)}
							/>
							<Controller
								name="memoryAlertThreshold"
								control={control}
								render={({ field }) => (
									<SliderWithLabel
										{...field}
										sliderMaxWidth={{ xs: "100%", md: "50%" }}
										fieldLabel={t(
											"pages.createMonitor.form.thresholds.option.memoryThreshold.label"
										)}
										min={0}
										max={100}
										step={1}
										valueLabelDisplay="auto"
										valueLabelFormat={(value) => `${value}%`}
									/>
								)}
							/>
							<Controller
								name="diskAlertThreshold"
								control={control}
								render={({ field }) => (
									<SliderWithLabel
										{...field}
										sliderMaxWidth={{ xs: "100%", md: "50%" }}
										fieldLabel={t(
											"pages.createMonitor.form.thresholds.option.diskThreshold.label"
										)}
										min={0}
										max={100}
										step={1}
										valueLabelDisplay="auto"
										valueLabelFormat={(value) => `${value}%`}
									/>
								)}
							/>
							<Controller
								name="tempAlertThreshold"
								control={control}
								render={({ field }) => (
									<SliderWithLabel
										{...field}
										sliderMaxWidth={{ xs: "100%", md: "50%" }}
										fieldLabel={t(
											"pages.createMonitor.form.thresholds.option.tempThreshold.label"
										)}
										min={0}
										max={100}
										step={1}
										valueLabelDisplay="auto"
										valueLabelFormat={(value) => `${value}°C`}
									/>
								)}
							/>
						</Stack>
					}
				/>
			)}

			<ConfigBox
				title={t("pages.createMonitor.form.incidents.title")}
				subtitle={t("pages.createMonitor.form.incidents.description")}
				rightContent={
					<Stack spacing={theme.spacing(LAYOUT.MD)}>
						<Controller
							name="statusWindowSize"
							control={control}
							render={({ field }) => (
								<SliderWithLabel
									{...field}
									sliderMaxWidth={{ xs: "100%", md: "50%" }}
									fieldLabel={t("pages.createMonitor.form.incidents.option.checks.label")}
									min={1}
									max={25}
									valueLabelDisplay="auto"
								/>
							)}
						/>
						<Controller
							name="statusWindowThreshold"
							control={control}
							render={({ field }) => (
								<SliderWithLabel
									{...field}
									sliderMaxWidth={{ xs: "100%", md: "50%" }}
									fieldLabel={t(
										"pages.createMonitor.form.incidents.option.percentage.label"
									)}
									min={1}
									max={100}
									valueLabelDisplay="auto"
								/>
							)}
						/>
					</Stack>
				}
			/>

			<ConfigBox
				title={t("pages.createMonitor.form.notifications.title")}
				subtitle={t("pages.createMonitor.form.notifications.description")}
				rightContent={
					<Controller
						name="notifications"
						control={control}
						render={({ field }) => {
							const notificationOptions = (notifications ?? []).map((n) => ({
								...n,
								name: n.notificationName,
							}));
							const notificationConfigs = field.value ?? [];
							const selectedNotifications = notificationOptions.filter((n) =>
								notificationConfigs.some((config) => config.channelId === n.id)
							);
							return (
								<Stack spacing={theme.spacing(LAYOUT.MD)}>
									<Autocomplete
										multiple
										options={notificationOptions}
										value={selectedNotifications}
										getOptionLabel={(option) => option.name}
										onChange={(_: unknown, newValue: typeof notificationOptions) => {
											field.onChange(
												newValue.map((notification) => {
													return (
														notificationConfigs.find(
															(config) => config.channelId === notification.id
														) ?? { channelId: notification.id }
													);
												})
											);
										}}
										isOptionEqualToValue={(option, value) => option.id === value.id}
									/>
									{selectedNotifications.length > 0 && (
										<Stack
											flex={1}
											width="100%"
										>
											{selectedNotifications.map((notification, index) => (
												<Stack
													direction="row"
													alignItems="center"
													key={notification.id}
													width="100%"
												>
													<Typography flexGrow={1}>
														{notification.notificationName}
													</Typography>
													<IconButton
														size="small"
														onClick={() => {
															field.onChange(
																notificationConfigs.filter(
																	(item) => item.channelId !== notification.id
																)
															);
														}}
														aria-label="Remove notification"
													>
														<Trash2 size={16} />
													</IconButton>
													{index < selectedNotifications.length - 1 && <Divider />}
												</Stack>
											))}
										</Stack>
									)}
								</Stack>
							);
						}}
					/>
				}
			/>

			<ConfigBox
				title={t("pages.createMonitor.form.escalation.title")}
				subtitle={t("pages.createMonitor.form.escalation.description")}
				rightContent={
					<Controller
						name="notifications"
						control={control}
						render={({ field }) => {
							const notificationOptions = (notifications ?? []).map((n) => ({
								...n,
								name: n.notificationName,
							}));
							const notificationConfigs = field.value ?? [];
							const selectedNotifications = notificationOptions.filter((n) =>
								notificationConfigs.some((config) => config.channelId === n.id)
							);

							if (selectedNotifications.length === 0) {
								return null;
							}

							return (
								<Stack spacing={theme.spacing(LAYOUT.MD)}>
									{selectedNotifications.map((notification) => {
										const config =
											notificationConfigs.find((item) => item.channelId === notification.id) ?? {
												channelId: notification.id,
											};
										const escalationOptions = notificationOptions;

										return (
											<Stack
												key={notification.id}
												spacing={theme.spacing(LAYOUT.SM)}
												sx={{ border: 1, borderColor: "divider", borderRadius: 1, p: 2 }}
											>
												<Typography fontWeight={600}>{notification.notificationName}</Typography>
												<Select
													value={config.escalation?.channelId ?? ""}
													fieldLabel={t("pages.createMonitor.form.escalation.option.notifications.label")}
													onChange={(event) => {
														const escalationChannelId = event.target.value;
														field.onChange(
															notificationConfigs.map((item) => {
																if (item.channelId !== notification.id) {
																	return item;
																}

																if (!escalationChannelId) {
																	return { channelId: item.channelId };
																}

																return {
																	channelId: item.channelId,
																	escalation: {
																		channelId: escalationChannelId,
																		delayMinutes: item.escalation?.delayMinutes ?? 30,
																	},
																};
															})
														);
													}}
												>
													<MenuItem value="">
														{t("pages.createMonitor.form.escalation.option.notifications.placeholder")}
													</MenuItem>
													{escalationOptions.map((option) => (
														<MenuItem key={option.id} value={option.id}>
															{option.notificationName}
														</MenuItem>
													))}
												</Select>
												<TextField
													value={config.escalation?.delayMinutes ?? ""}
													onChange={(event) => {
														const delayMinutes = Number(event.target.value || 0);
														field.onChange(
															notificationConfigs.map((item) => {
																if (item.channelId !== notification.id) {
																	return item;
																}

																const escalationChannelId = item.escalation?.channelId ?? notification.id;

																return {
																	channelId: item.channelId,
																	escalation: {
																		channelId: escalationChannelId,
																		delayMinutes,
																	},
																};
															})
														);
													}}
													type="number"
													fieldLabel={t("pages.createMonitor.form.escalation.option.delay.label")}
													placeholder={t("pages.createMonitor.form.escalation.option.delay.placeholder")}
													fullWidth
												/>
											</Stack>
										);
									})}
								</Stack>
							);
						}}
					/>
				}
			/>

			{(watchedType === "http" ||
				watchedType === "grpc" ||
				watchedType === "websocket") && (
				<ConfigBox
					title={t("pages.createMonitor.form.ignoreTls.title")}
					subtitle={t("pages.createMonitor.form.ignoreTls.description")}
					rightContent={
						<Controller
							name="ignoreTlsErrors"
							control={control}
							render={({ field }) => (
								<Stack
									direction="row"
									alignItems="center"
									spacing={theme.spacing(SPACING.LG)}
								>
									<Switch
										checked={field.value ?? false}
										onChange={(e) => field.onChange(e.target.checked)}
									/>
									<Typography>
										{t("pages.createMonitor.form.ignoreTls.option.tls.label")}
									</Typography>
								</Stack>
							)}
						/>
					}
				/>
			)}

			{watchedType === "http" && (
				<ConfigBox
					title={t("pages.createMonitor.form.advanced.title")}
					subtitle={t("pages.createMonitor.form.advanced.description")}
					rightContent={
						<Stack spacing={theme.spacing(LAYOUT.MD)}>
							<Controller
								name="useAdvancedMatching"
								control={control}
								render={({ field }) => (
									<Stack
										direction="row"
										alignItems="center"
										spacing={theme.spacing(SPACING.LG)}
									>
										<Switch
											checked={field.value ?? false}
											onChange={(e) => field.onChange(e.target.checked)}
										/>
										<Typography>
											{t(
												"pages.createMonitor.form.advanced.option.advancedMatching.label"
											)}
										</Typography>
									</Stack>
								)}
							/>
							{watchedUseAdvancedMatching && (
								<Stack spacing={theme.spacing(LAYOUT.MD)}>
									<Controller
										name="matchMethod"
										control={control}
										render={({ field }) => (
											<Select
												{...field}
												value={field.value ?? "equal"}
												fieldLabel={t(
													"pages.createMonitor.form.advanced.option.matchMethod.label"
												)}
											>
												<MenuItem value="equal">
													{t(
														"pages.createMonitor.form.advanced.option.matchMethod.equal"
													)}
												</MenuItem>
												<MenuItem value="include">
													{t(
														"pages.createMonitor.form.advanced.option.matchMethod.include"
													)}
												</MenuItem>
												<MenuItem value="regex">
													{t(
														"pages.createMonitor.form.advanced.option.matchMethod.regex"
													)}
												</MenuItem>
											</Select>
										)}
									/>
									<Controller
										name="expectedValue"
										control={control}
										render={({ field, fieldState }) => (
											<TextField
												{...field}
												value={field.value ?? ""}
												fieldLabel={t(
													"pages.createMonitor.form.advanced.option.expectedValue.label"
												)}
												fullWidth
												error={!!fieldState.error}
												helperText={fieldState.error?.message ?? ""}
											/>
										)}
									/>
									<Controller
										name="jsonPath"
										control={control}
										render={({ field, fieldState }) => (
											<TextField
												{...field}
												value={field.value ?? ""}
												fieldLabel={t(
													"pages.createMonitor.form.advanced.option.jsonPath.label"
												)}
												fullWidth
												error={!!fieldState.error}
												helperText={fieldState.error?.message ?? ""}
											/>
										)}
									/>
									<Typography
										component="span"
										color="text.secondary"
										sx={{ opacity: 0.8 }}
									>
										<Trans
											i18nKey="pages.createMonitor.form.advanced.option.jsonPath.description"
											components={{
												jmesLink: (
													<Link
														href="https://jmespath.org/"
														target="_blank"
														rel="noopener noreferrer"
													/>
												),
											}}
										/>
									</Typography>
								</Stack>
							)}
						</Stack>
					}
				/>
			)}

			{supportsGeoCheck(watchedType) && (
				<ConfigBox
					title={t("pages.createMonitor.form.geoChecks.title")}
					subtitle={t("pages.createMonitor.form.geoChecks.description")}
					rightContent={
						<Stack spacing={theme.spacing(LAYOUT.MD)}>
							<Controller
								name="geoCheckEnabled"
								control={control}
								render={({ field }) => (
									<Stack
										direction="row"
										alignItems="center"
										spacing={theme.spacing(SPACING.LG)}
									>
										<Switch
											checked={field.value ?? false}
											onChange={(e) => field.onChange(e.target.checked)}
										/>
										<Typography>
											{t("pages.createMonitor.form.geoChecks.option.enabled.label")}
										</Typography>
									</Stack>
								)}
							/>
							{watchGeoCheckEnabled && (
								<Stack spacing={theme.spacing(LAYOUT.MD)}>
									<Controller
										name="geoCheckLocations"
										control={control}
										render={({ field }) => {
											// Map continents to have 'name' property for Autocomplete
											const locationOptions = GeoContinents.map((continent) => ({
												id: continent,
												name: t(
													`pages.createMonitor.form.geoChecks.option.locations.options.${continent}`
												),
											}));
											const selectedLocations = locationOptions.filter((loc) =>
												(field.value ?? []).includes(loc.id)
											);
											return (
												<Stack spacing={theme.spacing(LAYOUT.MD)}>
													<Autocomplete
														multiple
														options={locationOptions}
														value={selectedLocations}
														getOptionLabel={(option) => option.name}
														onChange={(_: unknown, newValue: typeof locationOptions) => {
															field.onChange(newValue.map((loc) => loc.id));
														}}
														isOptionEqualToValue={(option, value) =>
															option.id === value.id
														}
														fieldLabel={t(
															"pages.createMonitor.form.geoChecks.option.locations.label"
														)}
													/>
													{selectedLocations.length > 0 && (
														<Stack
															flex={1}
															width="100%"
														>
															{selectedLocations.map((location, index) => (
																<Stack
																	direction="row"
																	alignItems="center"
																	key={location.id}
																	width="100%"
																>
																	<Typography flexGrow={1}>{location.name}</Typography>
																	<IconButton
																		size="small"
																		onClick={() => {
																			field.onChange(
																				(field.value ?? []).filter(
																					(id: string) => id !== location.id
																				)
																			);
																		}}
																		aria-label="Remove location"
																	>
																		<Trash2 size={16} />
																	</IconButton>
																	{index < selectedLocations.length - 1 && <Divider />}
																</Stack>
															))}
														</Stack>
													)}
												</Stack>
											);
										}}
									/>
									<Controller
										name="geoCheckInterval"
										control={control}
										render={({ field }) => (
											<Select
												{...field}
												value={field.value ?? 300000}
												fieldLabel={t(
													"pages.createMonitor.form.geoChecks.option.interval.label"
												)}
											>
												<MenuItem value={300000}>
													{t(
														"pages.createMonitor.form.geoChecks.option.interval.value.fiveMinutes"
													)}
												</MenuItem>
												<MenuItem value={600000}>
													{t(
														"pages.createMonitor.form.geoChecks.option.interval.value.tenMinutes"
													)}
												</MenuItem>
												<MenuItem value={900000}>
													{t(
														"pages.createMonitor.form.geoChecks.option.interval.value.fifteenMinutes"
													)}
												</MenuItem>
												<MenuItem value={1800000}>
													{t(
														"pages.createMonitor.form.geoChecks.option.interval.value.thirtyMinutes"
													)}
												</MenuItem>
											</Select>
										)}
									/>
								</Stack>
							)}
						</Stack>
					}
				/>
			)}

			<Stack
				direction="row"
				justifyContent="flex-end"
			>
				<Button
					loading={isSubmitting}
					type="submit"
					variant="contained"
					color="primary"
				>
					{t("common.buttons.save")}
				</Button>
			</Stack>
			<Dialog
				open={isDeleteDialogOpen}
				title={t("common.dialogs.delete.title")}
				content={t("common.dialogs.delete.description")}
				onConfirm={handleDeleteConfirm}
				onCancel={handleDeleteCancel}
				loading={isDeleting}
			/>
		</BasePage>
	);
};

export default CreateMonitorPage;

const SERVICE_NAME = "JobQueueHelper";
import type { Monitor } from "@/types/monitor.js";
import { supportsGeoCheck } from "@/types/monitor.js";
import { AppError } from "@/utils/AppError.js";
import {
	ICheckService,
	INetworkService,
	INotificationsService,
	ISettingsService,
	IStatusService,
	IncidentService,
	type IGeoChecksService,
} from "@/service/index.js";
import { CHECK_TTL_SENTINEL, type MaintenanceWindow, type StatusChangeResult } from "@/types/index.js";
import {
	IMaintenanceWindowsRepository,
	IMonitorsRepository,
	ITeamsRepository,
	IMonitorStatsRepository,
	IChecksRepository,
	IIncidentsRepository,
	IGeoChecksRepository,
} from "@/repositories/index.js";
import { ILogger } from "@/utils/logger.js";
import { IBufferService } from "@/service/index.js";

export interface ISuperSimpleQueueHelper {
	readonly serviceName: string;
	getHeartbeatJob(): (monitor: Monitor) => Promise<void>;
	getHeartbeatGeoJob(): (monitor: Monitor) => Promise<void>;
	getCleanupOrphanedJob(): () => Promise<void>;
	getCleanupRetentionJob(): () => Promise<void>;
	isInMaintenanceWindow(monitorId: string, teamId: string): Promise<boolean>;
	getEscalationJob(): () => Promise<void>;
}

export interface MonitorActionDecision {
	shouldCreateIncident: boolean;
	shouldResolveIncident: boolean;
	shouldSendNotification: boolean;
	incidentReason: "status_down" | "threshold_breach" | null;
	notificationReason: "status_change" | "threshold_breach" | null;
	thresholdBreaches?: {
		cpu?: boolean;
		memory?: boolean;
		disk?: boolean;
		temp?: boolean;
	};
}

export class SuperSimpleQueueHelper implements ISuperSimpleQueueHelper {
	static SERVICE_NAME = SERVICE_NAME;

	private logger: ILogger;
	private networkService: INetworkService;
	private statusService: IStatusService;
	private notificationsService: INotificationsService;
	private checkService: ICheckService;
	private settingsService: ISettingsService;
	private buffer: IBufferService;
	private incidentService: IncidentService;
	private maintenanceWindowsRepository: IMaintenanceWindowsRepository;
	private monitorsRepository: IMonitorsRepository;
	private teamsRepository: ITeamsRepository;
	private monitorStatsRepository: IMonitorStatsRepository;
	private checksRepository: IChecksRepository;
	private incidentsRepository: IIncidentsRepository;
	private geoChecksService: IGeoChecksService;
	private geoChecksRepository: IGeoChecksRepository;
	private escalationState: Map<string, { incidentId: string; nextEligibleAtByKey: Map<string, number> }>;

	constructor(
		logger: ILogger,
		networkService: INetworkService,
		statusService: IStatusService,
		notificationsService: INotificationsService,
		checkService: ICheckService,
		settingsService: ISettingsService,
		buffer: IBufferService,
		incidentService: IncidentService,
		maintenanceWindowsRepository: IMaintenanceWindowsRepository,
		monitorsRepository: IMonitorsRepository,
		teamsRepository: ITeamsRepository,
		monitorStatsRepository: IMonitorStatsRepository,
		checksRepository: IChecksRepository,
		incidentsRepository: IIncidentsRepository,
		geoChecksService: IGeoChecksService,
		geoChecksRepository: IGeoChecksRepository
	) {
		this.logger = logger;
		this.networkService = networkService;
		this.statusService = statusService;
		this.checkService = checkService;
		this.settingsService = settingsService;
		this.buffer = buffer;
		this.notificationsService = notificationsService;
		this.incidentService = incidentService;
		this.maintenanceWindowsRepository = maintenanceWindowsRepository;
		this.monitorsRepository = monitorsRepository;
		this.teamsRepository = teamsRepository;
		this.monitorStatsRepository = monitorStatsRepository;
		this.checksRepository = checksRepository;
		this.incidentsRepository = incidentsRepository;
		this.geoChecksService = geoChecksService;
		this.geoChecksRepository = geoChecksRepository;
		this.escalationState = new Map();
	}

	get serviceName() {
		return SuperSimpleQueueHelper.SERVICE_NAME;
	}

	getHeartbeatJob = () => {
		return async (monitor: Monitor) => {
			try {
				const monitorId = monitor.id;
				const teamId = monitor.teamId;
				if (!monitorId) {
					throw new AppError({ message: "No monitor id", service: SERVICE_NAME, method: "getMonitorJob" });
				}

				// Step 1.  Check for maintenance window, if found, skip the check

				const maintenanceWindowActive = await this.isInMaintenanceWindow(monitorId, teamId);
				if (maintenanceWindowActive) {
					this.logger.debug({
						message: `Monitor ${monitorId} is in maintenance window`,
						service: SERVICE_NAME,
						method: "getMonitorJob",
					});
					if (monitor.status !== "maintenance") {
						await this.monitorsRepository.updateById(monitorId, teamId, { status: "maintenance" });
					}
					return;
				}

				// Step 2.  Request monitor status
				const status = await this.networkService.requestStatus(monitor);
				if (!status) {
					throw new Error("No network response");
				}

				// Step 3.  Build check
				const check = this.checkService.buildCheck(status);
				if (!check) {
					this.logger.warn({
						message: `No check could be built for monitor ${monitorId}`,
						service: SERVICE_NAME,
						method: "getMonitorJob",
						details: { code: status.code, message: status.message },
					});
					return;
				}
				// Step 4 Add check to buffer
				this.buffer.addToBuffer(check);
				// Step 4.  Update monitor status
				const statusChangeResult = await this.statusService.updateMonitorStatus(status, check);

				// Step 5.  Get decisions
				const decision = this.evaluateMonitorAction(statusChangeResult);

				// Step 6. Handle notifications (best effort, continue even in event of failure, don't wait)
				if (decision.shouldSendNotification) {
					this.notificationsService.handleNotifications(statusChangeResult.monitor, status, decision).catch((error: unknown) => {
						this.logger.error({
							message: `Error sending notifications for job ${statusChangeResult.monitor.id}: ${error instanceof Error ? error.message : "Unknown error"}`,
							service: SERVICE_NAME,
							method: "getMonitorJob",
							stack: error instanceof Error ? error.stack : undefined,
						});
					});
				}

				// Step 7. Handle incidents (best effort, don't wait)
				this.incidentService.handleIncident(statusChangeResult.monitor, statusChangeResult.code, decision, status).catch((error: unknown) => {
					this.logger.warn({
						message: `Error handling incident for job ${monitor.id}: ${error instanceof Error ? error.message : "Unknown error"}`,
						service: SERVICE_NAME,
						method: "getMonitorJob",
						stack: error instanceof Error ? error.stack : undefined,
					});
				});
			} catch (error: unknown) {
				this.logger.warn({
					message: error instanceof Error ? error.message : "Unknown error",
					service: SERVICE_NAME,
					method: "getMonitorJob",
					stack: error instanceof Error ? error.stack : undefined,
				});
				throw error;
			}
		};
	};

	getCleanupOrphanedJob = () => {
		return async () => {
			try {
				this.logger.info({
					message: "Starting cleanup of orphaned data",
					service: SERVICE_NAME,
					method: "getCleanupOrphanedJob",
				});

				// Get all valid team IDs
				const validTeamIds = await this.teamsRepository.findAllTeamIds();
				if (!validTeamIds || validTeamIds.length === 0) {
					this.logger.warn({
						message: "No valid teams returned; skipping orphan cleanup to avoid accidental mass deletion",
						service: SERVICE_NAME,
						method: "getCleanupOrphanedJob",
					});
					return;
				}
				this.logger.debug({
					message: `Found ${validTeamIds.length} valid teams`,
					service: SERVICE_NAME,
					method: "getCleanupOrphanedJob",
				});

				// Remove orphaned monitors (monitors without a valid team)
				const deletedMonitorCount = await this.monitorsRepository.deleteByTeamIdsNotIn(validTeamIds);
				if (deletedMonitorCount > 0) {
					this.logger.info({
						message: `Deleted ${deletedMonitorCount} orphaned monitors`,
						service: SERVICE_NAME,
						method: "getCleanupOrphanedJob",
					});
				}

				// Remove orphaned monitorStats (stats without a valid monitor)
				const allMonitorIds = await this.monitorsRepository.findAllMonitorIds();
				if (!allMonitorIds || allMonitorIds.length === 0) {
					this.logger.warn({
						message: "No valid monitors returned; skipping monitor-linked orphan cleanup",
						service: SERVICE_NAME,
						method: "getCleanupOrphanedJob",
					});
					return;
				}
				this.logger.debug({
					message: `Found ${allMonitorIds.length} valid monitors`,
					service: SERVICE_NAME,
					method: "getCleanupOrphanedJob",
				});

				const deletedStatsCount = await this.monitorStatsRepository.deleteByMonitorIdsNotIn(allMonitorIds);
				if (deletedStatsCount > 0) {
					this.logger.info({
						message: `Deleted ${deletedStatsCount} orphaned monitor stats`,
						service: SERVICE_NAME,
						method: "getCleanupOrphanedJob",
					});
				}

				// Remove orphaned checks
				const deletedChecksCount = await this.checksRepository.deleteByMonitorIdsNotIn(allMonitorIds);
				if (deletedChecksCount > 0) {
					this.logger.info({
						message: `Deleted ${deletedChecksCount} orphaned checks`,
						service: SERVICE_NAME,
						method: "getCleanupOrphanedJob",
					});
				}

				// Remove orphaned incidents
				const deletedIncidentsCount = await this.incidentsRepository.deleteByMonitorIdsNotIn(allMonitorIds);
				if (deletedIncidentsCount > 0) {
					this.logger.info({
						message: `Deleted ${deletedIncidentsCount} orphaned incidents`,
						service: SERVICE_NAME,
						method: "getCleanupOrphanedJob",
					});
				}

				// Remove orphaned geo checks
				const deletedGeoChecksCount = await this.geoChecksRepository.deleteByMonitorIdsNotIn(allMonitorIds);
				if (deletedGeoChecksCount > 0) {
					this.logger.info({
						message: `Deleted ${deletedGeoChecksCount} orphaned geo checks`,
						service: SERVICE_NAME,
						method: "getCleanupOrphanedJob",
					});
				}

				this.logger.info({
					message: "Cleanup of orphaned data completed",
					service: SERVICE_NAME,
					method: "getCleanupOrphanedJob",
				});
			} catch (error: unknown) {
				this.logger.warn({
					message: error instanceof Error ? error.message : "Unknown error",
					service: SERVICE_NAME,
					method: "getCleanupOrphanedJob",
					stack: error instanceof Error ? error.stack : undefined,
				});
				throw error;
			}
		};
	};

	getHeartbeatGeoJob = () => {
		return async (monitor: Monitor) => {
			try {
				const monitorId = monitor.id;
				const teamId = monitor.teamId;

				// Step 1: Validate monitor eligibility
				if (!monitorId) {
					throw new AppError({ message: "No monitor id", service: SERVICE_NAME, method: "getHeartbeatGeoJob" });
				}

				if (!monitor.geoCheckEnabled) {
					return;
				}
				if (!supportsGeoCheck(monitor.type)) {
					this.logger.debug({
						message: `Monitor ${monitorId} type does not support geo checks, skipping`,
						service: SERVICE_NAME,
						method: "getHeartbeatGeoJob",
					});
					return;
				}

				if (!monitor.geoCheckLocations || monitor.geoCheckLocations.length === 0) {
					this.logger.warn({
						message: `No geo check locations configured for monitor ${monitorId}`,
						service: SERVICE_NAME,
						method: "getHeartbeatGeoJob",
					});
					return;
				}

				// Step 2: Check for maintenance window
				const maintenanceWindowActive = await this.isInMaintenanceWindow(monitorId, teamId);
				if (maintenanceWindowActive) {
					this.logger.debug({
						message: `Monitor ${monitorId} is in maintenance window, skipping geo check`,
						service: SERVICE_NAME,
						method: "getHeartbeatGeoJob",
					});
					return;
				}

				// Step 3: Build geo check (handles API calls and polling)
				const geoCheck = await this.geoChecksService.buildGeoCheck(monitor);
				if (!geoCheck) {
					this.logger.warn({
						message: `No geo check could be built for monitor ${monitorId}`,
						service: SERVICE_NAME,
						method: "getHeartbeatGeoJob",
					});
					return;
				}

				// Step 4: Add geo check to buffer
				this.buffer.addGeoCheckToBuffer(geoCheck);

				this.logger.debug({
					message: `Geo check job executed for monitor ${monitorId}`,
					service: SERVICE_NAME,
					method: "getHeartbeatGeoJob",
				});
			} catch (error: unknown) {
				this.logger.error({
					message: error instanceof Error ? error.message : "Unknown error",
					service: SERVICE_NAME,
					method: "getHeartbeatGeoJob",
					stack: error instanceof Error ? error.stack : undefined,
				});
				// Don't throw - geo check failures shouldn't crash the job scheduler
			}
		};
	};

	async isInMaintenanceWindow(monitorId: string, teamId: string) {
		const maintenanceWindows = await this.maintenanceWindowsRepository.findByMonitorId(monitorId, teamId);
		// Check for active maintenance window:
		const maintenanceWindowIsActive = maintenanceWindows.reduce((acc: boolean, window: MaintenanceWindow) => {
			if (window.active) {
				const start = new Date(window.start);
				const end = new Date(window.end);
				const now = new Date();
				const repeatInterval = window.repeat || 0;

				// If start is < now and end > now, we're in maintenance
				if (start <= now && end >= now) return true;

				// If maintenance window was set in the past with a repeat,
				// we need to advance start and end to see if we are in range

				while (start < now && repeatInterval !== 0) {
					start.setTime(start.getTime() + repeatInterval);
					end.setTime(end.getTime() + repeatInterval);
					if (start <= now && end >= now) {
						return true;
					}
				}
				return false;
			}
			return acc;
		}, false);
		return maintenanceWindowIsActive;
	}

	getCleanupRetentionJob = () => {
		return async () => {
			try {
				const settings = await this.settingsService.getDBSettings();

				const checkTTL = settings.checkTTL; // Check TTL is in DAYS, not MS

				if (checkTTL === CHECK_TTL_SENTINEL) {
					this.logger.info({
						message: `Check TTL is set to unlimited, skipping cleanup`,
						service: SERVICE_NAME,
						method: "getCleanupRetentionJob",
					});
					return;
				}
				const checkTTLInMs = checkTTL * 24 * 60 * 60 * 1000;
				const cutoffDate = new Date(Date.now() - checkTTLInMs);
				const deleteCount = await this.checkService.deleteOlderThan(cutoffDate);
				this.logger.info({
					message: `Deleted ${deleteCount} checks older than ${cutoffDate.toISOString()}`,
					service: SERVICE_NAME,
					method: "getCleanupRetentionJob",
				});
			} catch (error: unknown) {
				this.logger.error({
					message: error instanceof Error ? error.message : "Unknown error",
					service: SERVICE_NAME,
					method: "getCleanupRetentionJob",
					stack: error instanceof Error ? error.stack : undefined,
				});
			}
		};
	};

	private evaluateMonitorAction(statusChangeResult: StatusChangeResult): MonitorActionDecision {
		const { monitor, statusChanged, prevStatus } = statusChangeResult;

		// Initialize result
		const decision: MonitorActionDecision = {
			shouldCreateIncident: false,
			shouldResolveIncident: false,
			shouldSendNotification: false,
			incidentReason: null,
			notificationReason: null,
		};

		if (!statusChanged) {
			return decision;
		}

		if (monitor.status === "down") {
			// Monitor went down (unreachable)
			decision.shouldCreateIncident = true;
			decision.shouldSendNotification = true;
			decision.incidentReason = "status_down";
			decision.notificationReason = "status_change";
		} else if (monitor.status === "breached") {
			// Hardware monitor exceeded thresholds
			decision.shouldCreateIncident = true;
			decision.shouldSendNotification = true;
			decision.incidentReason = "threshold_breach";
			decision.notificationReason = "threshold_breach";
		} else if (monitor.status === "up" && (prevStatus === "down" || prevStatus === "breached")) {
			// Monitor recovered from down or breached state
			decision.shouldResolveIncident = true;
			decision.shouldSendNotification = true;
			decision.notificationReason = "status_change";
		}

		return decision;
	}
	getEscalationJob = () => {
		return async () => {
			try {
				this.logger.debug({
					message: "Starting escalation check",
					service: SERVICE_NAME,
					method: "getEscalationJob",
				});

				const monitors = await this.monitorsRepository.findAll();
				if (!monitors) {
					return;
				}

				for (const monitor of monitors) {
					const notificationConfigs = monitor.notifications?.filter((notification) => notification.escalation?.channelId) ?? [];
					if (notificationConfigs.length === 0) {
						this.escalationState.delete(monitor.id);
						continue;
					}

					const activeIncident = await this.incidentsRepository.findActiveByMonitorId(monitor.id, monitor.teamId);
					if (!activeIncident) {
						this.escalationState.delete(monitor.id);
						continue;
					}

					const currentState = this.escalationState.get(monitor.id);
					const nextEligibleAtByKey =
						currentState?.incidentId === activeIncident.id
							? currentState.nextEligibleAtByKey
							: new Map<string, number>();
					const incidentStartTime = Number(activeIncident.startTime) || new Date(activeIncident.startTime).getTime();
					const now = Date.now();
					const incidentDurationMinutes = (now - incidentStartTime) / 1000 / 60;

					for (const notification of notificationConfigs) {
						if (!notification.escalation) {
							continue;
						}

						const escalationKey = `${notification.channelId}:${notification.escalation.channelId}:${notification.escalation.delayMinutes}`;
						const nextEligibleAt = nextEligibleAtByKey.get(escalationKey) ?? incidentStartTime + notification.escalation.delayMinutes * 60 * 1000;
						if (incidentDurationMinutes < notification.escalation.delayMinutes || now < nextEligibleAt) {
							continue;
						}

						try {
							await this.notificationsService.handleNotifications(
								{
									...monitor,
									notifications: [{ channelId: notification.escalation.channelId }],
								},
								{
									monitorId: monitor.id,
									teamId: monitor.teamId,
									type: monitor.type,
									status: false,
									code: activeIncident.statusCode || 500,
									message: activeIncident.message || "Monitor still down",
									responseTime: 0,
								},
								{
									shouldSendNotification: true,
									notificationReason: "status_change",
									shouldCreateIncident: false,
									shouldResolveIncident: false,
									incidentReason: null,
								}
							);
						} catch (error: unknown) {
							this.logger.warn({
								message: `Failed to send escalation for monitor ${monitor.id}: ${error instanceof Error ? error.message : "Unknown error"}`,
								service: SERVICE_NAME,
								method: "getEscalationJob",
								stack: error instanceof Error ? error.stack : undefined,
							});
							continue;
						}

						nextEligibleAtByKey.set(
							escalationKey,
							now + notification.escalation.delayMinutes * 60 * 1000
						);
					}

					this.escalationState.set(monitor.id, {
						incidentId: activeIncident.id,
						nextEligibleAtByKey,
					});
				}
